def intentos_de_ordenes_cerradas(apps, schema_editor):
    """Cada orden ya cerrada pasa a tener su visita registrada (con el técnico y supervisor actuales)."""
    Orden = apps.get_model("operaciones", "OrdenTrabajo")
    Intento = apps.get_model("operaciones", "Intento")
    nuevos = []
    for o in (Orden.objects.filter(estado__in=["completada", "fallida", "reprogramada"], fecha_ejecucion__isnull=False)
              .select_related("tecnico").iterator(chunk_size=2000)):
        nuevos.append(Intento(orden_id=o.pk, numero=1, tecnico_id=o.tecnico_id,
                              supervisor_id=o.tecnico.supervisor_id if o.tecnico_id else None,
                              fecha=o.fecha_ejecucion, resultado=o.estado,
                              motivo_no_resuelto="" if o.estado == "completada" else o.motivo_no_resuelto,
                              minutos_reales=o.minutos_reales, inicio_trabajo=o.inicio_trabajo,
                              fin_trabajo=o.fin_trabajo))
    Intento.objects.bulk_create(nuevos, batch_size=2000)


